using System.Text.Json;
using W=System.Windows;
using C=System.Windows.Controls;
using M=System.Windows.Media;
using F=System.Windows.Forms;
using U=VelvetVoice.UiControls;
namespace CombinedStudio;
internal sealed class CrosshairPage:C.ScrollViewer {
 readonly CrosshairStore store;readonly CrosshairOverlay overlay;CrosshairHotkey hotkey;
 readonly CrosshairRandomizer randomizer;
 readonly C.TextBlock status=U.Text("Overlay is off. Choose a design, then enable it.",13,U.Muted);
 readonly C.CheckBox enabled=new(){Content="Enable crosshair overlay",Foreground=U.Ink,FontSize=16,Margin=new W.Thickness(0,8,0,14)};
 readonly CrosshairView preview;readonly C.WrapPanel saved=new();readonly C.TextBox name=new(){Text="My crosshair",MinWidth=210,MinHeight=40,Margin=new W.Thickness(0,0,10,10)};
 readonly List<Action> bindings=new();bool syncing;readonly bool fixture;readonly System.Windows.Threading.DispatcherTimer saveTimer=new(){Interval=TimeSpan.FromMilliseconds(400)};
 internal CrosshairPage(W.Window owner,string testRoot=null){fixture=testRoot!=null;store=new(testRoot??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"YAIOpc","Crosshair"));overlay=new(store.Settings,store.Folder);preview=new(){Design=store.Settings.Design,ImageFolder=store.Folder,Height=220};
  VerticalScrollBarVisibility=C.ScrollBarVisibility.Auto;HorizontalScrollBarVisibility=C.ScrollBarVisibility.Disabled;var page=new C.StackPanel{Margin=new W.Thickness(30,24,30,24),MaxWidth=1100};Content=page;
  page.Children.Add(U.Text("CROSSHAIR STUDIO",32));page.Children.Add(U.Text("Design your crosshair. Keep it centered over your game.",14,U.Muted));
  var live=U.Section("Live preview");live.Children.Add(new C.Border{Background=new M.LinearGradientBrush(((M.SolidColorBrush)U.Tone("#243841")).Color,((M.SolidColorBrush)U.Tone("#151F29")).Color,45),CornerRadius=new W.CornerRadius(10),Child=preview,Margin=new W.Thickness(0,0,0,12)});enabled.Click+=(_,_)=>Run(()=>overlay.SetEnabled(enabled.IsChecked==true));live.Children.Add(enabled);live.Children.Add(U.Text("Works over windowed and borderless games. Use borderless mode if an exclusive fullscreen game covers the overlay.",12,U.Muted));page.Children.Add(U.Card(live));
  randomizer=new CrosshairRandomizer(store,Select,RenderSaved);page.Children.Add(U.Card(randomizer));
  var gallery=U.Section("Crosshair library","32 built-in designs. Choose one, then fine-tune it below.");var choices=new C.WrapPanel();foreach(var preset in CrosshairStore.BuiltIn()){var tile=new C.StackPanel();tile.Children.Add(new CrosshairView{Design=preset.Design,Width=120,Height=65});tile.Children.Add(U.Text(preset.Name,12));choices.Children.Add(Button(tile,()=>Select(preset.Design.Copy())));}gallery.Children.Add(new C.Expander{Header="Browse all 32 designs",Foreground=U.Ink,Content=choices});page.Children.Add(U.Card(gallery));
  var editor=U.Section("Designer");editor.Children.Add(Choice("Shape",CrosshairDesign.Shapes,()=>store.Settings.Design.Shape,value=>{if(value=="Image"&&string.IsNullOrEmpty(store.Settings.Design.ImageFile))throw new ArgumentException("Import a PNG image first.");store.Settings.Design.Shape=value;}));
  var colors=new C.WrapPanel();colors.Children.Add(ColorEntry("Crosshair color",()=>store.Settings.Design.Color,value=>store.Settings.Design.Color=value));colors.Children.Add(ColorEntry("Outline color",()=>store.Settings.Design.OutlineColor,value=>store.Settings.Design.OutlineColor=value));editor.Children.Add(colors);
  var palette=new C.WrapPanel();foreach(string color in new[]{"#55FF88","#55DDFF","#FFFFFF","#FF5555","#FFD855","#DD88FF"}){var swatch=Button(color,()=>{store.Settings.Design.Color=color;Changed();});swatch.Foreground=U.Tone(color);palette.Children.Add(swatch);}editor.Children.Add(palette);
  var sliders=new C.Grid();sliders.ColumnDefinitions.Add(new(){Width=new W.GridLength(1,W.GridUnitType.Star)});sliders.ColumnDefinitions.Add(new(){Width=new W.GridLength(1,W.GridUnitType.Star)});
  var controls=new W.UIElement[]{Scale("Line length",1,60,()=>store.Settings.Design.Length,value=>store.Settings.Design.Length=value),Scale("Line thickness",1,12,()=>store.Settings.Design.Thickness,value=>store.Settings.Design.Thickness=value),Scale("Center gap",0,40,()=>store.Settings.Design.Gap,value=>store.Settings.Design.Gap=value),Scale("Dot size",1,20,()=>store.Settings.Design.DotSize,value=>store.Settings.Design.DotSize=value),Scale("Ring radius",2,80,()=>store.Settings.Design.Radius,value=>store.Settings.Design.Radius=value),Scale("Outline width",0,6,()=>store.Settings.Design.Outline,value=>store.Settings.Design.Outline=value),Scale("Opacity %",5,100,()=>store.Settings.Design.Opacity,value=>store.Settings.Design.Opacity=value),Scale("Rotation °",0,359,()=>store.Settings.Design.Rotation,value=>store.Settings.Design.Rotation=value),Scale("Image size",8,200,()=>store.Settings.Design.ImageSize,value=>store.Settings.Design.ImageSize=value)};
  for(int i=0;i<controls.Length;i++){if(i%2==0)sliders.RowDefinitions.Add(new(){Height=W.GridLength.Auto});C.Grid.SetColumn(controls[i],i%2);C.Grid.SetRow(controls[i],i/2);sliders.Children.Add(controls[i]);}editor.Children.Add(sliders);editor.Children.Add(Toggle("Show center dot",()=>store.Settings.Design.Dot,value=>store.Settings.Design.Dot=value));var images=new C.WrapPanel();images.Children.Add(Button("Import PNG crosshair",ImportImage));images.Children.Add(Button("Export transparent PNG",ExportImage));editor.Children.Add(images);page.Children.Add(U.Card(editor));
  var position=U.Section("Monitor & position","Positions and sizes use physical pixels. The overlay stays click-through and never takes keyboard focus.");var screens=F.Screen.AllScreens;var monitors=new C.ComboBox{MinHeight=40,Margin=new W.Thickness(0,0,0,12),ItemsSource=screens.Select(screen=>screen.DeviceName+(screen.Primary?" · Primary":"")+" · "+screen.Bounds.Width+"×"+screen.Bounds.Height).ToArray()};monitors.SelectedIndex=Math.Max(0,Array.FindIndex(screens,screen=>screen.DeviceName==store.Settings.Monitor));monitors.SelectionChanged+=(_,_)=>{if(!syncing&&monitors.SelectedIndex>=0)Run(()=>{store.Settings.Monitor=screens[monitors.SelectedIndex].DeviceName;Changed();});};position.Children.Add(monitors);
  position.Children.Add(Scale("Horizontal offset",-2000,2000,()=>store.Settings.OffsetX,value=>store.Settings.OffsetX=value));position.Children.Add(Scale("Vertical offset",-2000,2000,()=>store.Settings.OffsetY,value=>store.Settings.OffsetY=value));position.Children.Add(Button("Recenter",()=>{store.Settings.OffsetX=store.Settings.OffsetY=0;Changed();}));position.Children.Add(Toggle("Hide while right mouse button is held (aim down sights)",()=>store.Settings.HideOnAim,value=>store.Settings.HideOnAim=value));position.Children.Add(Choice("Toggle shortcut: Ctrl + Alt +",new[]{"X","C","F8","F9"},()=>store.Settings.ToggleKey,value=>{store.Settings.ToggleKey=value;if(hotkey!=null&&!hotkey.Register(value))throw new InvalidOperationException("That shortcut is in use. Choose another key or toggle from this page.");}));page.Children.Add(U.Card(position));
  var library=U.Section("Saved presets","Save your current design or share a JSON preset.");var saveRow=new C.WrapPanel();W.Automation.AutomationProperties.SetName(name,"Crosshair preset name");saveRow.Children.Add(name);saveRow.Children.Add(Button("Save design",()=>{store.SavePreset(name.Text);RenderSaved();}));saveRow.Children.Add(Button("Import preset",ImportPreset));saveRow.Children.Add(Button("Export preset",ExportPreset));library.Children.Add(saveRow);library.Children.Add(saved);page.Children.Add(U.Card(library));page.Children.Add(status);
  overlay.Changed+=()=>{enabled.IsChecked=overlay.Enabled;status.Text=overlay.Enabled?"Overlay on · Ctrl + Alt + "+store.Settings.ToggleKey+" to hide":"Overlay off.";};saveTimer.Tick+=(_,_)=>{saveTimer.Stop();Run(store.Save);};
  owner.Loaded+=(_,_)=>{if(fixture)return;Run(()=>{hotkey=new(owner,()=>Run(()=>overlay.SetEnabled(!overlay.Enabled)));if(!hotkey.Register(store.Settings.ToggleKey))throw new InvalidOperationException("Crosshair shortcut is already in use. Choose a different key.");});};
  owner.Closed+=(_,_)=>{saveTimer.Stop();randomizer.Dispose();hotkey?.Dispose();overlay.Dispose();try{store.Save();}catch{}};
  Sync();RenderSaved();if(!string.IsNullOrEmpty(store.LoadError))status.Text=store.LoadError;
 }
 C.Button Button(object label,Action action){var button=new C.Button{Content=label,MinHeight=40,Margin=new W.Thickness(0,0,10,10),Padding=new W.Thickness(12,7,12,7)};button.Click+=(_,_)=>Run(action);return button;}
 void Run(Action action){try{action();}catch(Exception error){status.Text=error.GetBaseException().Message;Sync();}}
 void Select(CrosshairDesign design){design.Validate();if(design.Shape=="Image")CrosshairView.LoadImage(preview.ImagePath(design.ImageFile));store.Settings.Design=design;Changed();}
 void Changed(){Sync();overlay.Update();saveTimer.Stop();saveTimer.Start();}
 void Sync(){syncing=true;try{preview.Design=store.Settings.Design;preview.InvalidateVisual();foreach(var update in bindings)update();}finally{syncing=false;}}
 W.UIElement Scale(string caption,int min,int max,Func<int> read,Action<int> write){var row=new C.StackPanel{Margin=new W.Thickness(0,0,20,14)};var text=U.Text(caption,12,U.Muted);var slider=new C.Slider{Minimum=min,Maximum=max,IsSnapToTickEnabled=true,TickFrequency=1,SmallChange=1,LargeChange=5,MinHeight=26};W.Automation.AutomationProperties.SetName(slider,caption);row.Children.Add(text);row.Children.Add(slider);slider.ValueChanged+=(_,_)=>{if(!syncing)Run(()=>{write((int)slider.Value);Changed();});};bindings.Add(()=>{slider.Value=read();text.Text=caption+"  "+read();});return row;}
 W.UIElement Toggle(string caption,Func<bool> read,Action<bool> write){var toggle=new C.CheckBox{Content=caption,Foreground=U.Ink,Margin=new W.Thickness(0,4,0,14)};toggle.Click+=(_,_)=>Run(()=>{write(toggle.IsChecked==true);Changed();});bindings.Add(()=>toggle.IsChecked=read());return toggle;}
 W.UIElement Choice(string caption,string[] choices,Func<string> read,Action<string> write){var row=new C.StackPanel{Margin=new W.Thickness(0,0,0,12)};row.Children.Add(U.Text(caption,12,U.Muted));var choice=new C.ComboBox{ItemsSource=choices,MinHeight=40};choice.SelectionChanged+=(_,_)=>{if(!syncing&&choice.SelectedItem is string value)Run(()=>{write(value);Changed();});};bindings.Add(()=>choice.SelectedItem=read());row.Children.Add(choice);return row;}
 W.UIElement ColorEntry(string caption,Func<string> read,Action<string> write){var row=new C.StackPanel{Margin=new W.Thickness(0,0,20,12)};row.Children.Add(U.Text(caption,12,U.Muted));var input=new C.TextBox{MinHeight=38,Width=180};W.Automation.AutomationProperties.SetName(input,caption);void Commit(){if(syncing)return;Run(()=>{string value=input.Text.Trim().ToUpperInvariant();var copy=store.Settings.Design.Copy();copy.Color=value;copy.Validate();write(value);Changed();});}input.LostKeyboardFocus+=(_,_)=>Commit();input.KeyDown+=(_,e)=>{if(e.Key==System.Windows.Input.Key.Enter){Commit();e.Handled=true;}};bindings.Add(()=>input.Text=read());row.Children.Add(input);return row;}
 void RenderSaved(){saved.Children.Clear();foreach(var preset in store.Settings.Presets.ToArray()){var row=new C.StackPanel{Orientation=C.Orientation.Horizontal};row.Children.Add(Button(preset.Name,()=>Select(preset.Design.Copy())));var delete=Button("×",()=>{store.Settings.Presets.Remove(preset);store.Save();RenderSaved();});W.Automation.AutomationProperties.SetName(delete,"Delete "+preset.Name);row.Children.Add(delete);saved.Children.Add(row);}if(saved.Children.Count==0)saved.Children.Add(U.Text("Your saved designs appear here.",12,U.Muted));}
 void ImportImage(){var dialog=new Microsoft.Win32.OpenFileDialog{Filter="PNG images|*.png",Title="Import crosshair image"};if(dialog.ShowDialog()!=true)return;string file=store.ImportImage(dialog.FileName);var design=store.Settings.Design.Copy();design.Shape="Image";design.ImageFile=file;Select(design);}
 void ExportImage(){var dialog=new Microsoft.Win32.SaveFileDialog{Filter="PNG image|*.png",FileName="crosshair.png"};if(dialog.ShowDialog()==true){preview.ExportPng(dialog.FileName);status.Text="Transparent PNG exported.";}}
 void ImportPreset(){var dialog=new Microsoft.Win32.OpenFileDialog{Filter="Crosshair preset|*.json"};if(dialog.ShowDialog()==true){Select(store.ImportDesign(dialog.FileName));status.Text="Preset loaded. Save design to add it to your library.";}}
 void ExportPreset(){if(store.Settings.Design.Shape=="Image")throw new ArgumentException("Use Export transparent PNG for image crosshairs.");var dialog=new Microsoft.Win32.SaveFileDialog{Filter="Crosshair preset|*.json",FileName="crosshair.json"};if(dialog.ShowDialog()==true){var design=store.Settings.Design.Copy();design.ImageFile="";File.WriteAllText(dialog.FileName,JsonSerializer.Serialize(design,new JsonSerializerOptions{WriteIndented=true}));status.Text="Preset exported.";}}
 internal async Task Verify(string folder){
  await randomizer.Verify();
  var design=new CrosshairDesign{Shape="Ring + cross",Color="#55DDFF",Radius=14};Select(design);store.SavePreset("UI fixture");store.Save();var reloaded=new CrosshairStore(store.Folder);if(reloaded.Settings.Presets.Single().Design.Color!="#55DDFF")throw new Exception("Crosshair preset persistence failed");
  var foreground=CrosshairOverlay.GetForegroundWindow();overlay.SetEnabled(true);if((CrosshairOverlay.GetWindowLong(overlay.Handle,-20)&0x80000A0)!=0x80000A0||!overlay.Visible)throw new Exception("Crosshair click-through / nonactivating styles failed");if(CrosshairOverlay.GetForegroundWindow()!=foreground)throw new Exception("Crosshair overlay took keyboard focus");
  var screen=F.Screen.PrimaryScreen;var expected=CrosshairOverlay.Center(screen.Bounds,0,0);if(!CrosshairOverlay.GetWindowRect(overlay.Handle,out var rect)||rect.Left!=expected.X-160||rect.Top!=expected.Y-160||rect.Right-rect.Left!=320||rect.Bottom-rect.Top!=320)throw new Exception("Overlay native position failed");
  overlay.SetEnabled(false);if(overlay.Visible)throw new Exception("Crosshair overlay did not hide");await randomizer.Verify();preview.ExportPng(Path.Combine(folder,"crosshair-export.png"));RenderSaved();
 }
}
